// Error handling middleware - MUST be last
const errorHandler = (err, req, res, next) => {
  // Log comprehensive error details for debugging
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV !== 'production' ? err.stack : undefined,
    type: err.constructor.name,
    url: req.url,
    method: req.method,
    ip: req.ip || req.connection.remoteAddress,
  });

  // Security: Never expose error details to clients in production
  if (err.status === 400 || err.status === 422) {
    // For validation errors, return minimal information
    return res.status(err.status).json({
      error: 'Invalid request',
    });
  } else if (err.status === 401 || err.status === 403) {
    // Authentication/authorization errors
    return res.status(err.status).json({
      error: 'Access denied',
    });
  } else if (err.status === 404) {
    return res.status(404).json({
      error: 'Resource not found',
    });
  } else if (err.status === 429) {
    return res.status(429).json({
      error: 'Too many requests',
    });
  } else if (err.status >= 500) {
    // Server errors - log but never expose details
    // In production, consider using error tracking services like Sentry
    return res.status(500).json({
      error: 'Internal server error',
    });
  }

  // Default error response
  res.status(err.status || 500).json({
    error: err.status === 429 ? err.message : 'Internal server error',
  });
};

