  console.error(JSON.stringify({
    timestamp: new Date().toISOString(),
    level: 'error',
    message: err.message,
    method: req.method,
    url: req.url,
    ip: req.ip || req.connection.remoteAddress,
    userId: req.user?.id,
    // Only include stack in non-production
    stack: process.env.NODE_ENV !== 'production' ? err.stack : undefined
  }));
  ```

### 3. **Security Best Practice Additions**

#### a. **CORS Configuration**
- **Current**: No explicit CORS middleware
- **Recommendation**: Add explicit CORS middleware with whitelisted origins
- **Add**:
  ```javascript
  const cors = require('cors');

  const corsOptions = {
    origin: (process.env.ALLOWED_ORIGINS || '').split(','),
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'],
    allowedHeaders: ['Content-Type', 'Authorization'],
    credentials: true,
    maxAge: 86400 // 24 hours
  };

  app.use(cors(corsOptions));
  ```

#### b. **CSRF Protection**
- **Recommendation**: Add CSRF protection for state-changing operations
- **Add**:
  ```javascript
  const csrf = require('csurf');

  const csrfProtection = csrf({ 
    cookie: {
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'strict'
    }
  });

  // Apply to state-changing endpoints
  app.post('/users', csrfProtection, validateUserCreate, handleValidationErrors, handler);
