// Safe error handling middleware
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);

  if (!errors.isEmpty()) {
    // Sanitize error values to prevent XSS in validation error responses
    const sanitizedErrors = errors.array().map(err => ({
      field: err.path,
      message: err.msg,
      value: typeof err.value === 'string' ? err.value.replace(/[<>]/g, '') : err.value,
    }));

    return res.status(400).json({
      error: 'Validation failed',
      details: sanitizedErrors,
    });
  }

  next();
};

// Error handling middleware - MUST be last
const errorHandler = (err, req, res, next) => {
  // Log error details for debugging (but don't expose to client)
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV !== 'production' ? err.stack : undefined,
    type: err.constructor.name,
  });

  // Handle specific error types with appropriate responses
  if (err.name === 'ValidationError') {
    return res.status(400).json({
      error: 'Validation error',
      message: 'Invalid request data',
    });
  }

  if (err.name === 'SyntaxError' && err.status === 400 && 'body' in err) {
    return res.status(400).json({
      error: 'Invalid JSON',
      message: 'Request body contains invalid JSON',
    });
  }

  // Define custom error codes for different types of errors
  const errorResponses = {
    'JsonWebTokenError': { status: 401, message: 'Invalid authentication token' },
    'TokenExpiredError': { status: 401, message: 'Authentication token expired' },
    'RangeError': { status: 400, message: 'Invalid parameter range' },
  };

  // Check if we have a specific response for this error type
  const specificError = errorResponses[err.name];
  if (specificError) {
    return res.status(specificError.status).json({
      error: specificError.message,
    });
  }

  // Send generic error message to client (security best practice)
  res.status(err.status || 500).json({
    error: err.status === 429 ? err.message : 'Internal server error',
  });
};

