  /<script[^>]*>/i,
  /javascript:/i,
  /on\w+\s*=/i,
  /data:\s*text\/html/i,
  /base64,/i,
  /\.\.\//g,
  /etc\/passwd/i,
  /\/etc\/shadow/i
];

const detectAttack = (req, res, next) => {
  const checkString = (str) => {
    if (typeof str !== 'string') return false;
    return BLOCKED_PATTERNS.some(pattern => pattern.test(str));
  };

  // Check body
  if (req.body) {
    const checkObject = (obj) => {
      for (const key in obj) {
        if (typeof obj[key] === 'string' && checkString(obj[key])) {
          return true;
        }
        if (typeof obj[key] === 'object' && obj[key] !== null && checkObject(obj[key])) {
          return true;
        }
      }
      return false;
    };

    if (checkObject(req.body)) {
      return res.status(400).json({ error: 'Malformed request detected' });
    }
  }

  // Check query parameters
  if (req.query) {
    for (const key in req.query) {
      if (checkString(req.query[key])) {
        return res.status(400).json({ error: 'Malformed request detected' });
      }
    }
  }

  next();
};

