    .bail()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .bail()
    .customSanitizer(value => sanitizeInput(value))
    .matches(/^[a-zA-Z\s'’-]+$/u) // Updated to support Unicode apostrophes
    .withMessage('Name can only contain letters, spaces, and apostrophes/hyphens'),

