/**
 * Sanitize user inputs to prevent XSS attacks
 * Escapes HTML characters that could be used for XSS
 */
function escapeXSS(str) {
  if (typeof str !== 'string') return str;
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;')
    .replace(/\//g, '&#x2F;');
}

/**
 * Normalize and sanitize input with additional security
 * Prevents XSS, directory traversal, and other injection attacks
 */
function sanitizeInput(input) {
  if (!input) return input;

  if (typeof input === 'string') {
    // Escape XSS
    input = escapeXSS(input.trim());
    // Remove null bytes
    input = input.replace(/\0/g, '');
    // Remove path traversal patterns
    input = input.replace(/\.\.\//g, '').replace(/\.\.\\\\/g, '');
    // Limit length to prevent DoS
    return input.slice(0, 10000);
  }

  if (Array.isArray(input)) {
    return input.map(item => sanitizeInput(item));
  }

  if (input && typeof input === 'object') {
    const sanitized = {};
    for (const key in input) {
      if (Object.prototype.hasOwnProperty.call(input, key)) {
        sanitized[key] = sanitizeInput(input[key]);
      }
    }
    return sanitized;
  }

  return input;
}

